modes.shape:
enum TicketStatus {
  Todo, Blocked, InProgress, InQa, Done, Cancelled
}

enum Classification {
  Clean,   // every blocker terminal -> fork master
  Stacked, // one in-flight parent -> stack, 1 deep
  Blocked, // a dependency isn't ready -> wait
  Hold,    // held off frontier (groom-gate/operator)
}

enum CrewKind {
  Worker, Sailor, Hand, Captain, Lookout, Admiral
}

enum CogState {
  Worker(WorkerState),
  Sailor(SailorState),
  Hand(HandState),
  Captain(CaptainState),
  Lookout(LookoutState),
}
enum WorkerState { Started, Implementing, Review,
  Waiting, Concluded, Escalated, Anchored }
enum SailorState { Sleeping, Escalated, Anchored }
enum HandState { Awaiting, Implementing,
  Concluded, Done, Anchored }
enum CaptainState { Done, Escalated }
enum LookoutState { Reviewed, Escalated }

enum PipelineStatus {
  Running, Success, Failed, Canceled, Manual
}

enum EntityKind {
  Session, Ticket, Ship, Escalation,
  Ticker, Convoy, Lookout
}

struct Report {
  session: SessionId,          // PK = FK
  state: CogState,             // per cog (5 kinds)
  last_action: Option<String>,
  reported_at: Timestamp,
}

struct Proposal {
  id: ProposalId,
  from_ticket: Option<TicketKey>,
  proposed: Proposed,
  created_at: Timestamp,
  ended_at: Option<Timestamp>,    // None = open
  accepted_as: Option<TicketKey>, // ended w/o = dropped
}
enum Proposed {
  New(TicketDraft),
  Existing { ticket: TicketKey, why: String,
             convoy: Option<ConvoyKey> },
}

struct ShipView {
  ship: Ship,
  snapshot: Option<ShipSnapshot>,
  fetch_ref: String,
  ours: bool,
}

struct ReviewState {
  open_threads: i64,
  total_threads: i64,
  threads: Vec<ReviewThread>,
  floating_notes: Vec<FloatingNote>,
}
struct ReviewThread {
  id: String,   // fleetc reply --thread
  path: Option<String>,
  line: Option<i64>,
  author: Option<String>,
  body: String,
}
struct FloatingNote {
  id: i64,
  author: Option<String>,
  created_at: String,
  body: String,
}

struct CiReport {
  status: Option<PipelineStatus>,
  failed: Vec<FailedJob>,
}
struct FailedJob {
  name: String,
  url: String,
  log_excerpt: String,
}
